//! Where a module sits on the MasterHUB base, from the USB port chain it enumerates on.
//!
//! The base's connectors are fixed, and each one is a distinct port chain below the base's own hub. The slot table
//! (`data/base-slots.json`, generated by `scripts/extract-base-slots.mjs` from the geometry of the official app's base
//! drawing) maps a module class and that chain, relative to the hub, to the cell its footprint starts at.
//!
//! A lookup tries, in order: positions seen on our hardware ([`observed`]), the slot table (less the entries in
//! [`VENDOR_ERRATA`]), then the connector geometry ([`geometry`]), which places any module on any connector.

use cooltek_sdk_service::ServiceModule;
use serde::Deserialize;
use std::{collections::HashMap, sync::OnceLock};

/// Where the base's own HID interface sits below its hub; it never moves, so it gives the hub's chain away.
const BASE_SLOT: [u8; 3] = [1, 4, 4];

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq)]
pub struct Slot {
    pub col: i8,
    pub row: i8,
    /// The turn the official drawing applies to the module, in degrees, in its own (portrait) frame.
    pub official_rotation: u16,
}

impl Slot {
    /// How far the module's artwork is turned clockwise from upright in our landscape frame, which is the official
    /// portrait drawing turned a quarter: 270 in the official drawing is upright here. A quarter or three-quarter
    /// turn also stands the footprint up, so a 4 x 2 module takes 2 columns and 4 rows.
    pub fn turn(&self) -> u16 {
        (self.official_rotation + 90) % 360
    }
}

#[derive(Deserialize)]
struct Table {
    modules: HashMap<String, HashMap<String, Slot>>,
}

fn table() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(|| {
        serde_json::from_str(include_str!("../data/base-slots.json"))
            .expect("data/base-slots.json is valid")
    })
}

/// Slots seen or inferred on our unit that the official drawing has no entry for (the module hung over the base's edge).
/// [`geometry`] now gives the same three; they stay as the place for a position our hardware contradicts it on.
fn observed(module: &str, slot: &str) -> Option<Slot> {
    match (module, slot) {
        // 11 October 2026: the 15-key module's top row one cell above the base, over the faders.
        ("M4315", "111") => Some(Slot {
            col: 0,
            row: -1,
            official_rotation: 270,
        }),
        // 14 October 2026: connectors the official drawing has no 15-key entry for. On the 11 connectors both tables
        // share, the 15-key module and the 5-fader module line up on one edge for the same connector (bottom when
        // flat, left when standing up, right when upside down), and the entry above follows that too. The fader
        // entries for these connectors (`113`: column 4 standing up, `143`: column 2, row 0, flat) therefore give:
        ("M4315", "113") => Some(Slot {
            col: 4,
            row: 0,
            official_rotation: 0,
        }),
        ("M4315", "143") => Some(Slot {
            col: 2,
            row: -1,
            official_rotation: 270,
        }),
        _ => None,
    }
}

/// Slot-table entries from the official drawing that put the module about two cells away from its connector's
/// contact pad, where it cannot be plugged in: (module, connector, the connector whose entry it copies). Each is an
/// exact copy of the same module's entry for another connector (two connectors cannot put a module in the same
/// place), so [`geometry`] places these instead. Not yet checked on hardware.
const VENDOR_ERRATA: &[(&str, &str, &str)] = &[
    // The drawing: flat at column 2, row 2, as on `131`. The geometry: standing up at column 1, over the top edge;
    // the dial and the knobs on `124` agree with it.
    ("M032LE", "124", "131"),
    // The drawing: turned a quarter at column 2, row 0, as on `31`. The geometry: flat at column -1, over the left
    // edge; only the roller's entry on `121` backs it.
    ("M131E", "121", "31"),
];

/// The connector whose entry the slot-table entry for `key` on `slot` copies, when it is one of the [`VENDOR_ERRATA`].
fn erratum(key: &str, slot: &str) -> Option<&'static str> {
    VENDOR_ERRATA
        .iter()
        .find(|&&(module, connector, _)| (module, connector) == (key, slot))
        .map(|&(_, _, copied)| copied)
}

/// Each connector's 4-pin contact pad, in the official portrait frame (4 columns x 6 rows) and half cells, with the
/// way it faces in degrees: (slot, x, y, facing). Fitted to the official drawing's connector positions. `144` is the
/// base's own interface.
const PADS: &[(&str, i8, i8, u16)] = &[
    ("111", 1, 4, 270),
    ("112", 5, 2, 270),
    ("113", 8, 1, 0),
    ("114", 6, 7, 180),
    ("121", 5, 10, 270),
    ("122", 8, 9, 0),
    ("123", 4, 9, 0),
    ("124", 1, 8, 270),
    ("131", 4, 3, 180),
    ("132", 3, 0, 270),
    ("133", 6, 3, 180),
    ("134", 5, 0, 270),
    ("141", 0, 3, 180),
    ("142", 2, 3, 180),
    ("143", 1, 0, 270),
    ("21", 4, 7, 180),
    ("22", 3, 4, 270),
    ("23", 5, 4, 270),
    ("24", 8, 3, 0),
    ("31", 4, 5, 0),
    ("32", 2, 7, 180),
    ("33", 0, 7, 180),
    ("34", 4, 1, 0),
    ("41", 8, 7, 0),
    ("42", 8, 5, 0),
    ("43", 5, 6, 270),
    ("44", 5, 8, 270),
];

/// A module's footprint in cells (columns x rows, unturned), where its pins sit on its underside (half cells, from
/// its top-left corner), and how far it turns beyond the pad's facing.
fn pins(module: ServiceModule) -> ((i8, i8), (i8, i8), u16) {
    match module {
        ServiceModule::M4315 => ((4, 3), (8, 3), 0),
        ServiceModule::M005S => ((4, 2), (8, 1), 0),
        ServiceModule::M131E | ServiceModule::M003K => ((2, 2), (4, 1), 0),
        ServiceModule::M032LE => ((4, 1), (5, 0), 90),
    }
}

/// Where `module` sits on connector `slot`, worked out from the pad and the module's pins: the pins land on the pad,
/// turned the way the pad faces. Agrees with every slot-table entry outside [`VENDOR_ERRATA`] and with [`observed`].
fn geometry(module: ServiceModule, slot: &str) -> Option<Slot> {
    let &(_, pad_x, pad_y, facing) = PADS.iter().find(|pad| pad.0 == slot)?;
    let ((width, height), (pin_x, pin_y), extra) = pins(module);
    let rotation = (facing + extra) % 360;
    let (width2, height2) = (2 * width, 2 * height);
    // The pins in the turned module, from its top-left corner.
    let (x, y) = match rotation {
        0 => (pin_x, pin_y),
        90 => (height2 - pin_y, pin_x),
        180 => (width2 - pin_x, height2 - pin_y),
        _ => (pin_y, width2 - pin_x),
    };
    let (col2, row2) = (pad_x - x, pad_y - y);
    if col2 % 2 != 0 || row2 % 2 != 0 {
        return None;
    }
    // The portrait frame turned a quarter clockwise is ours: its rows count our columns back from the right edge.
    let portrait_rows = if rotation % 180 == 90 { width } else { height };
    Some(Slot {
        col: 6 - row2 / 2 - portrait_rows,
        row: col2 / 2,
        official_rotation: rotation,
    })
}

fn module_key(module: ServiceModule) -> &'static str {
    match module {
        ServiceModule::M4315 => "M4315",
        ServiceModule::M032LE => "M032LE",
        ServiceModule::M005S => "M005S",
        ServiceModule::M131E => "M131E",
        ServiceModule::M003K => "M003K",
    }
}

/// The USB port chain of a macOS location ID: the ports below the bus, without the trailing zeros.
#[cfg(any(target_os = "macos", test))]
pub fn location_id_chain(location_id: u32) -> Vec<u8> {
    let mut ports: Vec<u8> = (0..6)
        .map(|index| ((location_id >> (20 - 4 * index)) & 0x0f) as u8)
        .collect();
    while ports.last() == Some(&0) {
        ports.pop();
    }
    ports
}

/// The chain of the base's hub, taken from the chain the base's own interface enumerates on.
pub fn hub_prefix(base_chain: &[u8]) -> Option<Vec<u8>> {
    let hub = base_chain.strip_suffix(&BASE_SLOT)?;
    (!hub.is_empty()).then(|| hub.to_vec())
}

/// The connector slot of a module: its chain below the hub, the port numbers written one after another.
pub fn slot_name(chain: &[u8], hub: &[u8]) -> Option<String> {
    let below = chain.strip_prefix(hub).filter(|below| !below.is_empty())?;
    Some(below.iter().map(|port| port.to_string()).collect())
}

pub fn lookup(module: ServiceModule, slot: &str) -> Option<Slot> {
    let key = module_key(module);
    observed(key, slot)
        .or_else(|| vendor(key, slot))
        .or_else(|| geometry(module, slot))
}

/// The slot-table entry, unless it is one of the [`VENDOR_ERRATA`].
fn vendor(key: &str, slot: &str) -> Option<Slot> {
    if erratum(key, slot).is_some() {
        return None;
    }
    table()
        .modules
        .get(key)
        .and_then(|slots| slots.get(slot))
        .copied()
}

/// `chain` as dotted text for diagnostics, for example `1.1.2.3`.
pub fn chain_text(chain: &[u8]) -> String {
    chain
        .iter()
        .map(u8::to_string)
        .collect::<Vec<_>>()
        .join(".")
}

#[cfg(test)]
mod tests {
    use super::*;

    // The chains recorded in docs/masterhub-hardware-results.md, with the hub at 1.1 (base at 1.1.1.4.4).
    const HUB: [u8; 2] = [1, 1];
    fn at(module: ServiceModule, chain: &[u8]) -> Option<(i8, i8)> {
        lookup(module, &slot_name(chain, &HUB)?).map(|slot| (slot.col, slot.row))
    }

    #[test]
    fn the_hub_comes_from_the_bases_own_chain() {
        assert_eq!(hub_prefix(&[1, 1, 1, 4, 4]), Some(vec![1, 1]));
        assert_eq!(hub_prefix(&[2, 1, 1, 4, 4]), Some(vec![2, 1]));
        assert_eq!(hub_prefix(&[1, 4, 4]), None);
        assert_eq!(hub_prefix(&[1, 1, 2, 3]), None);
    }

    #[test]
    fn a_slot_turns_the_module_from_upright_in_the_landscape_frame() {
        let turn = |module, chain: &[u8]| {
            lookup(module, &slot_name(chain, &HUB).unwrap()).map(|slot| slot.turn())
        };
        // Placed flat before (official 270): upright here.
        assert_eq!(turn(ServiceModule::M005S, &[1, 1, 2, 3]), Some(0));
        assert_eq!(turn(ServiceModule::M4315, &[1, 1, 1, 1, 1]), Some(0));
        // Official 0: standing up, 2 columns by 4 rows (hardware, 14 October 2026: faders top-right).
        assert_eq!(turn(ServiceModule::M005S, &[1, 1, 1, 1, 3]), Some(90));
        // Official 180.
        assert_eq!(turn(ServiceModule::M003K, &[1, 1, 2, 1]), Some(270));
        // The 15-key module standing up on the connector the faders stood up on.
        assert_eq!(turn(ServiceModule::M4315, &[1, 1, 1, 1, 3]), Some(90));
    }

    #[test]
    fn every_table_entry_fits_on_the_base_once_a_quarter_turn_stands_the_footprint_up() {
        for (module, name, columns, rows) in [
            (ServiceModule::M4315, "M4315", 4, 3),
            (ServiceModule::M032LE, "M032LE", 4, 1),
            (ServiceModule::M005S, "M005S", 4, 2),
            (ServiceModule::M131E, "M131E", 2, 2),
            (ServiceModule::M003K, "M003K", 2, 2),
        ] {
            assert_eq!(module_key(module), name);
            for (slot, found) in &table().modules[name] {
                let (width, height) = if found.turn().is_multiple_of(180) {
                    (columns, rows)
                } else {
                    (rows, columns)
                };
                assert!(
                    found.col >= 0
                        && found.row >= 0
                        && found.col + width <= 6
                        && found.row + height <= 4,
                    "{name} slot {slot} leaves the base"
                );
            }
        }
    }

    #[test]
    fn the_15_key_module_lines_up_with_the_faders_on_their_connectors() {
        let edge = |module, slot: &str| {
            let found = lookup(module, slot).unwrap();
            let (columns, rows) = if module == ServiceModule::M4315 {
                (4, 3)
            } else {
                (4, 2)
            };
            let (width, height) = if found.turn().is_multiple_of(180) {
                (columns, rows)
            } else {
                (rows, columns)
            };
            match found.official_rotation {
                270 => found.row + height,
                0 => found.col,
                180 => found.col + width,
                _ => found.row,
            }
        };
        // The connectors both tables have, plus the ones inferred from the faders.
        for slot in [
            "22", "23", "24", "33", "41", "42", "111", "112", "113", "122", "132", "134", "141",
            "143",
        ] {
            assert_eq!(
                edge(ServiceModule::M4315, slot),
                edge(ServiceModule::M005S, slot),
                "slot {slot}"
            );
        }
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 1, 1, 3]), Some((4, 0)));
    }

    #[test]
    fn the_first_arrangement_is_placed_from_the_table() {
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 2, 2]), Some((0, 0)));
        assert_eq!(at(ServiceModule::M032LE, &[1, 1, 1, 1, 4]), Some((0, 3)));
        assert_eq!(at(ServiceModule::M131E, &[1, 1, 1, 4, 3]), Some((4, 0)));
        assert_eq!(at(ServiceModule::M003K, &[1, 1, 1, 3, 4]), Some((4, 2)));
    }

    #[test]
    fn the_second_and_third_arrangements_are_placed_from_the_table() {
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 2, 3]), Some((0, 1)));
        assert_eq!(at(ServiceModule::M005S, &[1, 1, 2, 3]), Some((0, 2)));
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 1, 1, 1]), Some((0, -1)));
    }

    #[test]
    fn a_chain_outside_the_hub_or_on_no_connector_is_not_placed() {
        assert_eq!(slot_name(&[2, 1, 2, 3], &HUB), None);
        assert_eq!(slot_name(&[1, 1], &HUB), None);
        assert_eq!(at(ServiceModule::M4315, &[1, 1, 9, 9]), None);
    }

    #[test]
    fn the_table_covers_every_module_and_stays_on_the_base() {
        for module in [
            ServiceModule::M4315,
            ServiceModule::M032LE,
            ServiceModule::M005S,
            ServiceModule::M131E,
            ServiceModule::M003K,
        ] {
            let slots = &table().modules[module_key(module)];
            assert!(slots.len() >= 10, "{module:?} has {} slots", slots.len());
            assert!(
                slots
                    .values()
                    .all(|slot| (-4..6).contains(&slot.col) && (-4..4).contains(&slot.row))
            );
            assert!(
                slots
                    .values()
                    .all(|slot| matches!(slot.official_rotation, 0 | 90 | 180 | 270))
            );
        }
    }

    const MODULES: [ServiceModule; 5] = [
        ServiceModule::M4315,
        ServiceModule::M032LE,
        ServiceModule::M005S,
        ServiceModule::M131E,
        ServiceModule::M003K,
    ];

    #[test]
    fn the_geometry_agrees_with_the_table_and_the_hardware_observations() {
        let mut compared = 0;
        for module in MODULES {
            let key = module_key(module);
            for (slot, entry) in &table().modules[key] {
                if let Some(copied) = erratum(key, slot) {
                    assert_ne!(
                        geometry(module, slot),
                        Some(*entry),
                        "{key} {slot} is no erratum"
                    );
                    assert_eq!(
                        table().modules[key][copied],
                        *entry,
                        "{key} {slot} copies {copied}"
                    );
                    continue;
                }
                assert_eq!(geometry(module, slot), Some(*entry), "{key} slot {slot}");
                compared += 1;
            }
        }
        assert_eq!(compared, 90);
        for slot in ["111", "113", "143"] {
            assert_eq!(
                geometry(ServiceModule::M4315, slot),
                observed("M4315", slot),
                "slot {slot}"
            );
        }
    }

    #[test]
    fn every_module_is_placed_on_every_connector() {
        let slots: Vec<&str> = PADS.iter().map(|pad| pad.0).collect();
        assert_eq!(slots.len(), 27);
        for module in MODULES {
            for slot in &slots {
                let found = lookup(module, slot);
                assert!(found.is_some(), "{module:?} slot {slot}");
                let found = found.unwrap();
                assert!(matches!(found.official_rotation, 0 | 90 | 180 | 270));
                // The pins sit on a pad on the base, so a footprint hangs over an edge by less than its own size;
                // the furthest are the 15-key module on `121` (column -3) and modules over the top edge (row -2).
                assert!(
                    (-3..6).contains(&found.col) && (-2..4).contains(&found.row),
                    "{module:?} slot {slot} at {found:?}"
                );
            }
            // Every table connector has a pad, so the table adds no connector the geometry lacks.
            for slot in table().modules[module_key(module)].keys() {
                assert!(slots.contains(&slot.as_str()), "{module:?} slot {slot}");
            }
        }
        // The base's own interface is no module connector.
        assert_eq!(lookup(ServiceModule::M4315, "144"), None);
    }

    #[test]
    fn the_errata_are_placed_on_their_pads() {
        assert_eq!(
            lookup(ServiceModule::M032LE, "124"),
            Some(Slot {
                col: 1,
                row: -2,
                official_rotation: 0
            })
        );
        // Standing up (a quarter turn here) and flat.
        assert_eq!(
            lookup(ServiceModule::M032LE, "124").map(|slot| slot.turn()),
            Some(90)
        );
        assert_eq!(
            lookup(ServiceModule::M131E, "121").map(|slot| slot.turn()),
            Some(0)
        );
        assert_eq!(
            lookup(ServiceModule::M131E, "121"),
            Some(Slot {
                col: -1,
                row: 2,
                official_rotation: 270
            })
        );
    }

    #[test]
    fn a_location_id_reads_as_its_port_chain() {
        assert_eq!(location_id_chain(0x0211_2300), vec![1, 1, 2, 3]);
        assert_eq!(chain_text(&location_id_chain(0x0211_1110)), "1.1.1.1.1");
        // The base at 1.1.1.4.4 and another host port: the bus byte is dropped.
        assert_eq!(location_id_chain(0x0211_1440), vec![1, 1, 1, 4, 4]);
        assert_eq!(location_id_chain(0x0221_2300), vec![2, 1, 2, 3]);
        assert_eq!(location_id_chain(0x0211_9900), vec![1, 1, 9, 9]);
    }
}
